<style>
.news-account-shell{min-height:100vh;background:#09090b;color:#fff;padding:18px}.news-account-layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:18px;max-width:1440px;margin:0 auto}.account-sidebar{position:sticky;top:18px;display:flex;max-height:calc(100vh - 36px);min-height:calc(100vh - 36px);flex-direction:column;border:1px solid #27272a;border-radius:18px;background:#111113;padding:18px}.account-sidebar-brand{display:flex;align-items:center;gap:12px;border-bottom:1px solid #27272a;padding:4px 4px 18px;color:#fff;text-decoration:none}.account-sidebar-logo{display:grid;width:43px;height:43px;place-items:center;border-radius:13px;background:rgba(16,185,129,.14);color:#34d399;font-size:21px}.account-sidebar-brand small,.account-sidebar-brand strong{display:block}.account-sidebar-brand small{color:#71717a;font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.account-sidebar-brand strong{margin-top:3px;font-size:21px}.account-sidebar-nav{display:grid;gap:7px;margin-top:18px}.account-sidebar-link,.account-sidebar-logout{display:flex;min-height:45px;align-items:center;gap:12px;border:1px solid transparent;border-radius:11px;padding:0 13px;color:#a1a1aa;font-size:13px;font-weight:800;text-decoration:none}.account-sidebar-link i,.account-sidebar-logout i{width:18px;text-align:center}.account-sidebar-link:hover,.account-sidebar-link.is-active{border-color:#3f3f46;background:#202023;color:#fff}.account-sidebar-link.is-active i{color:#34d399}.account-sidebar-link.is-primary{margin:8px 0;background:#059669;color:#fff}.account-sidebar-footer{margin-top:auto;border-top:1px solid #27272a;padding-top:16px}.account-sidebar-logout{width:100%;background:rgba(220,38,38,.08);color:#fca5a5;cursor:pointer}.news-account-content{min-width:0;border:1px solid #202024;border-radius:18px;background:#0d0d0f;padding:clamp(22px,4vw,46px)}.news-kicker{margin:0;color:#34d399;font-size:11px;font-weight:900;letter-spacing:.2em;text-transform:uppercase}.news-title{margin:8px 0;font-size:clamp(30px,4vw,46px);line-height:1.1}.news-subtitle{margin:0;color:#a1a1aa}.news-actions{display:flex;gap:10px;margin-top:22px}.news-button{display:inline-flex;min-height:43px;align-items:center;justify-content:center;border:1px solid #3f3f46;border-radius:11px;padding:0 15px;color:#fff;font-size:13px;font-weight:800;text-decoration:none}.news-button.primary{border-color:#059669;background:#059669}.news-alert{margin:22px 0;border:1px solid rgba(16,185,129,.3);border-radius:12px;background:rgba(16,185,129,.1);padding:13px 15px;color:#a7f3d0}.news-list{display:grid;gap:12px;margin-top:30px}.news-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px;align-items:center;border:1px solid #29292d;border-radius:15px;background:#17171a;padding:18px}.news-row h2{margin:0 0 7px;font-size:18px}.news-meta{color:#a1a1aa;font-size:13px}.news-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.news-tag,.news-status{border-radius:999px;padding:5px 9px;font-size:10px;font-weight:900}.news-tag{background:#27272a;color:#d4d4d8}.news-status.pending{background:#451a03;color:#fcd34d}.news-status.published{background:#052e27;color:#6ee7b7}.news-empty{margin-top:30px;border:1px dashed #3f3f46;border-radius:15px;padding:32px;text-align:center;color:#71717a}.news-pagination{display:flex;justify-content:space-between;margin-top:20px}.news-pagination span{color:#52525b}.news-form{display:grid;gap:20px;margin-top:28px}.news-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.news-field.full{grid-column:1/-1}.news-field label{display:block;margin-bottom:8px;color:#d4d4d8;font-size:13px;font-weight:800}.news-field input,.news-field textarea,.news-field select{width:100%;border:1px solid #3f3f46;border-radius:12px;background:#17171a;padding:12px 14px;color:#fff;font:inherit;outline:none}.news-field input:focus,.news-field textarea:focus,.news-field select:focus{border-color:#10b981}.news-help{margin-top:6px;color:#71717a;font-size:12px}.news-error{margin:6px 0 0;color:#f87171;font-size:12px}.news-tag-options{display:flex;flex-wrap:wrap;gap:8px}.news-check{display:flex;align-items:center;gap:7px;border:1px solid #3f3f46;border-radius:999px;padding:8px 11px;color:#d4d4d8;font-size:12px}.news-check input{width:auto}.news-submit{min-height:50px;border:0;border-radius:12px;background:#059669;color:#fff;font-size:14px;font-weight:900;cursor:pointer}@media(max-width:860px){.news-account-layout{grid-template-columns:1fr}.account-sidebar{position:static;min-height:auto;max-height:none}.account-sidebar-footer{margin-top:16px}}@media(max-width:600px){.news-account-shell{padding:10px}.news-account-content{padding:22px 18px}.news-form-grid{grid-template-columns:1fr}.news-row{grid-template-columns:1fr}}
</style>
